import { StringColumn, DecimalColumn, Table, GenericColumn } from '../../db'

export const sys_app_category = Table({
    name: 'sys_app_category',
    extends: 'sys_metadata',
    schema: {
        default_order: DecimalColumn({ mandatory: false, label: 'Default order', read_only: false, active: true }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        style: StringColumn({
            mandatory: false,
            label: 'Style',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
    },
})
